import{_ as a,o as s,c as t,a8 as n}from"./chunks/framework.BppdKxCY.js";const h=JSON.parse('{"title":"EP.60 密钥零泄漏防线","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.60-secrets-zero-leak.md","filePath":"comics/EP.60-secrets-zero-leak.md","lastUpdated":1793421673000}'),o={name:"comics/EP.60-secrets-zero-leak.md"};function r(i,e,l,c,p,d){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="ep-60-密钥零泄漏防线" tabindex="-1">EP.60 密钥零泄漏防线 <a class="header-anchor" href="#ep-60-密钥零泄漏防线" aria-label="Permalink to &quot;EP.60 密钥零泄漏防线&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../47-secrets-management">第四十七部分 · 企业级密钥管理与零泄漏方案</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君觉得「打包压缩了就没人看」，把支付密钥 <code>sk_live_…</code> 直接写进代码 push 上去——结果提交 3 分钟就被安全机器人告警。压缩不是加密，前端产物是公开出版物，爬虫 24 小时扫公开仓库的新提交。</li><li><strong>第 2 格</strong>：码叔摆出密钥三级分类——publishable（Stripe pk_ / Sentry DSN / Maps key）可上船但要加 referrer 锁；restricted 带锁上船（IP / 域名 / 限额）；server-only（AWS AK/SK、支付 secret、数据库密码）永不下船，一律走 BFF 代理，前端只拿签名 URL 或短期 STS。</li><li><strong>第 3 格</strong>：像素酱这次学乖了——三道防线层层拦截：本地 gitleaks pre-commit 拦下提交、CI 扫描命中即 exit 1、GitHub Push Protection 平台级兜底。配上 <code>.env.local</code> 进 gitignore、<code>window.__ENV__</code> 运行时注入实现「build once, deploy many」。</li><li><strong>第 4 格</strong>：码叔结案——密钥进了 git 历史就等于已泄漏，应急四步：撤销旧密钥止血 → 双密钥并行轮换 → filter-repo 清洗历史 → 审计复盘。坑点提醒：日志与错误上报也是泄漏通道，异常 context 和 console 都要过脱敏器。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-压缩-加密" tabindex="-1">第 1 格 · 压缩 ≠ 加密 <a class="header-anchor" href="#第-1-格-·-压缩-加密" aria-label="Permalink to &quot;第 1 格 · 压缩 ≠ 加密&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const PAY_KEY = &#39;sk_live_9f8e…&#39;   // 写进源码</span></span>
<span class="line"><span>git push origin main              // 推送</span></span>
<span class="line"><span>→ 3 分钟后安全机器人告警</span></span></code></pre></div><p>构建工具的「压缩混淆」只是缩短变量名、删除空白——字符串字面量原样保留，<code>sk_live</code> 这种特征前缀在产物里全文可搜。公开仓库还有专门的爬虫实时订阅新提交事件，特征密钥几分钟内就会被扫走并尝试调用。</p><p><strong>铁律：前端产物 = 公开出版物</strong>，写进代码的每个字符串都要当作会出现在搜索引擎里。正文展开见 <a href="./../47-secrets-management#_47-1-密钥分级与前端无秘密全景">47.1</a>。</p><h3 id="第-2-格-·-密钥三级分类" tabindex="-1">第 2 格 · 密钥三级分类 <a class="header-anchor" href="#第-2-格-·-密钥三级分类" aria-label="Permalink to &quot;第 2 格 · 密钥三级分类&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>publishable → 可上前端(必须加 referrer/IP/限额锁)</span></span>
<span class="line"><span>restricted  → 可上前端(限制策略是底线)</span></span>
<span class="line"><span>server-only → 永不下船,BFF 代理</span></span></code></pre></div><p>分级判断标准只有一个问题：<strong>这把钥匙泄漏后，攻击者能造成不可控损失吗？</strong></p><ul><li>不能（只能刷配额、且有限制策略）→ publishable，可发前端；</li><li>能（调云 API、发起交易、读私有数据）→ server-only，永远留在服务端。</li></ul><p>server-only 的场景前端用三种「替代凭证」完成任务：BFF 代理转发、后端签发的预签名 URL、STS 短期 token。完整决策表见正文 <a href="./../47-secrets-management#_47-1-密钥分级与前端无秘密全景">47.1</a> 与 <a href="./../47-secrets-management#_47-6-第三方-key-的前端防护">47.6</a>。</p><h3 id="第-3-格-·-三道防线与注入隔离" tabindex="-1">第 3 格 · 三道防线与注入隔离 <a class="header-anchor" href="#第-3-格-·-三道防线与注入隔离" aria-label="Permalink to &quot;第 3 格 · 三道防线与注入隔离&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>防线1 本地:gitleaks pre-commit 拦截</span></span>
<span class="line"><span>防线2 CI:扫描命中即 exit 1</span></span>
<span class="line"><span>防线3 平台:GitHub Push Protection</span></span></code></pre></div><p>三道防线共用同一套原理——模式库（AKIA / sk- / ghp_ / JWT / 私钥块）+ 白名单（<code>process.env</code> 引用、文档占位符）+ 非零退出硬门禁。可运行的最小实现见 <a href="../examples/47-01-secret-scanner.ts">47-01-secret-scanner.ts</a>（虚拟仓库扫出 4 处泄漏、白名单零误报）。</p><p>注入侧的隔离同样关键：</p><ul><li><code>.env.local</code> 进 <code>.gitignore</code> 永不入库，<code>.env.example</code> 只留空壳模板；</li><li>多环境部署用<strong>运行时注入</strong>（<code>window.__ENV__</code> / config.json / envsubst），同一份产物跑三套环境；</li><li>应用入口加<strong>启动门禁</strong>：schema 校验必填/格式/枚举，缺失即拒启动，启动快照脱敏打印。见 <a href="../examples/47-02-env-guard.ts">47-02-env-guard.ts</a>，正文展开见 <a href="./../47-secrets-management#_47-2-本地开发-env-体系与团队分发">47.2</a> 与 <a href="./../47-secrets-management#_47-3-注入方案-构建期-vs-运行时与启动门禁">47.3</a>。</li></ul><h3 id="第-4-格-·-应急四步与日志脱敏" tabindex="-1">第 4 格 · 应急四步与日志脱敏 <a class="header-anchor" href="#第-4-格-·-应急四步与日志脱敏" aria-label="Permalink to &quot;第 4 格 · 应急四步与日志脱敏&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 撤销旧密钥(止血)  → ② 双密钥并行轮换</span></span>
<span class="line"><span>③ filter-repo 清史(整容) → ④ 审计复盘</span></span></code></pre></div><p>进了 git 历史就视为已泄漏——「删掉重新提交」毫无意义，历史里还在。<strong>顺序铁律：先止血再整容</strong>，否则清洗历史的几个小时里旧密钥仍在裸奔。轮换用双密钥并行期（old+new 同时有效 → 全部切新 → revoke 旧）避免线上 401 风暴。完整状态机见 <a href="../examples/47-04-leak-response.ts">47-04-leak-response.ts</a>。</p><p>密钥还有第二条泄漏通道：<strong>日志与监控上报</strong>。异常堆栈的 context、fetch 拦截器、console 都可能带密钥——两道闸门脱敏（key 名单 + value 模式），留头尾打码（<code>sk_l…wX9</code>）既安全又能排查对账。见 <a href="../examples/47-03-log-redactor.ts">47-03-log-redactor.ts</a>，正文展开见 <a href="./../47-secrets-management#_47-4-泄漏防控工具链-扫描、脱敏与应急响应">47.4</a>。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../47-secrets-management#_47-8-本章避坑清单">《47.8 本章避坑清单》</a></p></blockquote><ol><li><strong>把 server-only secret 写进前端代码</strong>：压缩混淆不藏字符串，打包后全网公开。secret 走 BFF 代理，前端只拿签名 URL / 短期凭证。</li><li><strong><code>.env.local</code> 误提交</strong>：git 历史永久留存。<code>.gitignore</code> 基线 + pre-commit 扫描双保险。</li><li><strong>扫描器无白名单</strong>：误报刷屏后开发者免疫，真泄漏被噪音埋没。放行 <code>process.env</code> 引用与文档占位符。</li><li><strong>泄漏后先删文件再补提交</strong>：历史里还在，等于没处理。按「撤销 → 轮换 → 清史 → 审计」四步走，先止血再整容。</li><li><strong>密钥硬切换</strong>：直接 revoke 旧 key，没切完的调用方面积 401。必须经双密钥并行期过渡。</li><li><strong>异常 message 带密钥</strong>：错误上报直接带走 secret。错误上下文只放 id，敏感字段过脱敏器。</li><li><strong>publishable key 裸奔</strong>：「可公开」不等于「无限制」。referrer 限制 + 用量上限 + 告警是底线三件套。</li></ol><h2 id="自测-3-题" tabindex="-1">自测 3 题 <a class="header-anchor" href="#自测-3-题" aria-label="Permalink to &quot;自测 3 题&quot;">​</a></h2><p><strong>1. 为什么说「压缩混淆」不能保护写在前端代码里的密钥？</strong></p><details><summary>参考答案</summary><p>压缩混淆只缩短标识符、删除空白与注释，<strong>字符串字面量原样保留</strong>——<code>sk_live_9f8e…</code> 在产物里全文可搜。而且密钥有特征前缀（AKIA / sk- / ghp_ / eyJ），扫描器用简单正则就能从整个 bundle 里把它捞出来。所以「打包了就没人看」是错觉：前端产物是公开出版物，写进去的每个字符串都应视为会出现在搜索引擎里。</p></details><p><strong>2. 密钥进了 git 历史后，为什么「撤销/轮换」必须排在「清洗历史」之前？</strong></p><details><summary>参考答案</summary><p>密钥进入 git 历史即视为已泄漏，攻击者随时可能已经在用。清洗历史（filter-repo/BFG + 协作者重克隆）通常需要数小时甚至跨天协调，如果先清洗再撤销，这段窗口期旧密钥仍然有效、仍在裸奔。正确顺序是先撤销旧密钥让攻击者手里的钥匙立即作废（止血），签发新密钥完成轮换（保服务），然后才从容清洗历史（整容），最后审计调用日志复盘。</p></details><p><strong>3. 同一份前端产物要同时部署到 dev / staging / prod 三套环境，配置注入该怎么做？</strong></p><details><summary>参考答案</summary><p>必须用<strong>运行时注入</strong>而不是构建期注入：构建期注入（<code>import.meta.env</code> 字符串替换）会把值固化进产物，切环境就得重新打包。运行时注入的常见方案：<code>window.__ENV__</code>（SSR 或容器启动时写入）、独立的 <code>config.js</code>（entrypoint 用 envsubst 替换占位符）、或前端启动时请求 BFF 的 <code>/api/config</code>。配合启动门禁做 schema 校验，缺配置直接拒启动并报出全部缺失项。</p></details>`,33)])])}const u=a(o,[["render",r]]);export{h as __pageData,u as default};
